import{_ as o,o as t,c as i,a2 as n}from"./chunks/framework.DGk0zlJw.js";const h=JSON.parse('{"title":"Beacon mission brief (distilled from the original plan; the original text is in mission-excerpt.md)","description":"","frontmatter":{},"headers":[],"relativePath":"mission.md","filePath":"mission.md"}'),r={name:"mission.md"};function a(s,e,l,c,d,g){return t(),i("div",null,[...e[0]||(e[0]=[n('<h1 id="beacon-mission-brief-distilled-from-the-original-plan-the-original-text-is-in-mission-excerpt-md" tabindex="-1">Beacon mission brief (distilled from the original plan; the original text is in mission-excerpt.md) <a class="header-anchor" href="#beacon-mission-brief-distilled-from-the-original-plan-the-original-text-is-in-mission-excerpt-md" aria-label="Permalink to &quot;Beacon mission brief (distilled from the original plan; the original text is in mission-excerpt.md)&quot;">​</a></h1><h2 id="positioning" tabindex="-1">Positioning <a class="header-anchor" href="#positioning" aria-label="Permalink to &quot;Positioning&quot;">​</a></h2><p><strong>Beacon = a developer status and action center resident on the Windows desktop (Developer Status &amp; Action Center)</strong>, not a Web Dashboard. Tagline: See what needs your attention. / Your development signal on Windows. Core: <strong>Signal + Action</strong> — it watches for you instead of making you go look (It watches for you).</p><h2 id="core-product-model-7-concepts" tabindex="-1">Core product model (7 concepts) <a class="header-anchor" href="#core-product-model-7-concepts" aria-label="Permalink to &quot;Core product model (7 concepts)&quot;">​</a></h2><ul><li><strong>Widget</strong>: the basic unit of information and interaction (GitHub PR Widget, CI Status Widget…)</li><li><strong>Provider</strong>: the data source (GitHub first; Jenkins/GitLab/Agent etc. in phase 2) — <strong>Provider First, never hard-wired into Core</strong>; credentials are configured once centrally instead of re-entering a token per widget</li><li><strong>Action</strong>: an operation that can be executed immediately (Run/Cancel/Retry/Open/Notify); the MVP does only simple actions (for example <code>workflow_dispatch</code>)</li><li><strong>Workflow</strong>: an advanced capability; the MVP does not build a complex engine</li><li><strong>Notification</strong>: proactive alerts (from CI / machine / workflow / widget thresholds), delivered through Windows Notifications</li><li>The remaining concepts are completed per the original text (Machine/Run etc.)</li></ul><h2 id="three-interaction-levels-progressive-disclosure-—-no-big-panel-up-front" tabindex="-1">Three interaction levels (progressive disclosure — no big panel up front) <a class="header-anchor" href="#three-interaction-levels-progressive-disclosure-—-no-big-panel-up-front" aria-label="Permalink to &quot;Three interaction levels (progressive disclosure — no big panel up front)&quot;">​</a></h2><ol><li><strong>Status Capsule</strong>: a small always-resident capsule on the desktop, showing only &quot;is there anything&quot;</li><li>Quick layer: one-click action buttons [Build] [Test] [Deploy]</li><li><strong>Detail Window</strong>: expands the details when needed (Build #1024 Status Failed Repo/Branch…)</li></ol><p>Entry points: <strong>Tray / Hotkey / Dock</strong>.</p><h2 id="key-design-pieces" tabindex="-1">Key design pieces <a class="header-anchor" href="#key-design-pieces" aria-label="Permalink to &quot;Key design pieces&quot;">​</a></h2><ul><li><strong>Notification Engine</strong>: rule-driven (if CI status == Failed → notify), not a bare Toast; Severity is one unified five-level scale (Info/Success/Warning/Error/Critical) and providers are not allowed to define their own states</li><li><strong>Tiered refresh strategy</strong>: PR 30–120 s, CI 10–30 s… never polling everything once a second; on failure show &quot;Unable to refresh, Last update 2min ago [Retry]&quot; rather than throwing the exception at the user</li><li><strong>Offline Mode</strong>: runnable while offline</li><li><strong>Local First</strong>: configuration lives on the machine (<code>%AppData%\\Beacon</code>: config/connections/widgets/pins.json — the original plan&#39;s <code>workflows.json</code> was never implemented, following the &quot;MVP does not do Workflow&quot; decision), <strong>secrets go to the Windows Secret Storage and are strictly forbidden in plain JSON</strong></li><li><strong>Architecture principle</strong>: Local First + Provider First; the Agent Server serves only as a connector and is not hard-wired</li></ul><h2 id="phasing" tabindex="-1">Phasing <a class="header-anchor" href="#phasing" aria-label="Permalink to &quot;Phasing&quot;">​</a></h2><ul><li><strong>Phase 1 (MVP)</strong>: GitHub Provider (PR/CI), Status Capsule, simple Actions, Notification, Tray/Hotkey, local configuration. <strong>Explicitly not done</strong>: a complex Workflow Engine, multiple Providers, agent coordination.</li><li><strong>Phase 2</strong>: Jenkins/GitLab/Docker/Machines/Agents/Generic REST Widget, Schedule, Webhook, Workflow, [Run Task] sent to an Agent — heading toward a Developer Control Plane. <ul><li><strong>Frozen record (2026-10-11, master-plan §2.3 decision ②)</strong>: GitLab/Docker/Machines/Agents/Workflow/[Run Task]/Control Plane are all <strong>frozen as not done</strong> (a long-term product boundary, not a postponement). Generic REST (<code>http.status</code>/<code>http.quota</code>) and the Webhook Action are already landed and unaffected. Jenkins is already landed (<code>jenkins.build</code>, an open-source standard JSON API, 2026-10-11 批3-补31).</li></ul></li></ul><h2 id="mvp-success-criteria-first-version-acceptance" tabindex="-1">MVP success criteria (first-version acceptance) <a class="header-anchor" href="#mvp-success-criteria-first-version-acceptance" aria-label="Permalink to &quot;MVP success criteria (first-version acceptance)&quot;">​</a></h2><p>A developer can: auto-start on boot → see the state in a corner of the desktop at all times → a one-click Run/Retry succeeds, all without <strong>opening a browser or signing in to GitHub</strong>.</p><h2 id="implementation-order-explicitly-required-by-the-original-plan" tabindex="-1">Implementation order (explicitly required by the original plan) <a class="header-anchor" href="#implementation-order-explicitly-required-by-the-original-plan" aria-label="Permalink to &quot;Implementation order (explicitly required by the original plan)&quot;">​</a></h2><p><strong>The first step is not to write code</strong>: produce ① a technical RFC ② a Solution / project layout ③ an MVP Issue list, then implement Phase 1 → Phase 2 incrementally — to stop it becoming an over-engineered Dashboard from the start. <strong>Documentation first.</strong></p>',16)])])}const u=o(r,[["render",a]]);export{h as __pageData,u as default};
